CREATE TABLE k_bank_chain (id INTEGER NOT NULL, bcvendor TEXT, entry1 TEXT NOT NULL, entry2 TEXT, entry3 TEXT, PRIMARY KEY(id));
CREATE TABLE k_content_path (id INTEGER NOT NULL, path TEXT NOT NULL, product_version_s TEXT, PRIMARY KEY(id));
CREATE TABLE k_mode (id INTEGER NOT NULL, name TEXT, PRIMARY KEY(id), UNIQUE(name));
CREATE TABLE k_category (id INTEGER NOT NULL, category TEXT, subcategory TEXT, subsubcategory TEXT, PRIMARY KEY(id));
CREATE TABLE k_sound_info (id INTEGER NOT NULL, name TEXT NOT NULL, author TEXT, comment TEXT, vendor TEXT, device_type_flags INTEGER NOT NULL DEFAULT 0, bank_chain_id INTEGER, content_path_id INTEGER NOT NULL, file_name TEXT NOT NULL, file_ext TEXT, uuid TEXT, PRIMARY KEY(id));
CREATE TABLE k_sound_info_category (sound_info_id INTEGER NOT NULL, category_id INTEGER NOT NULL, PRIMARY KEY(sound_info_id, category_id));
CREATE TABLE k_sound_info_mode (sound_info_id INTEGER NOT NULL, mode_id INTEGER NOT NULL, PRIMARY KEY(sound_info_id, mode_id));
CREATE VIEW v_sound_info(id, name, author, brand, product, bank, subbank, type, character, comment, device_type_flags, file_name, file_ext, uuid) AS SELECT s.id, name, author, iif(bcvendor != '', bcvendor, 'Native Instruments'), entry1, entry2, entry3, (SELECT group_concat(category || coalesce(', ' || subcategory, '') || coalesce(', ' || subsubcategory, ''), ', ') FROM k_category c JOIN k_sound_info_category sc ON c.id = sc.category_id WHERE sc.sound_info_id = s.id GROUP BY sc.sound_info_id), (SELECT group_concat(name, ', ') FROM k_mode m JOIN k_sound_info_mode sm ON m.id = sm.mode_id WHERE sm.sound_info_id = s.id GROUP BY sm.sound_info_id), comment, device_type_flags, file_name, file_ext, uuid FROM k_sound_info s JOIN k_bank_chain b ON s.bank_chain_id = b.id;
CREATE VIRTUAL TABLE f_sound_info USING fts5(name, author, brand, product, bank, subbank, type, character, comment, content='v_sound_info', content_rowid='id', tokenize="unicode61 remove_diacritics 2 tokenchars '#'");
